END $$;

-- Node 88 (A2-2.5.2) rev 8 -> 9
DO $$
DECLARE
  v_actual INT;
  v_expected INT := 8;
BEGIN
  SELECT published_rev INTO v_actual FROM kb_entry WHERE node_id = 88 FOR UPDATE;
  IF v_actual IS DISTINCT FROM v_expected THEN
    RAISE EXCEPTION 'Optimistic lock mismatch for node 88: expected %, got %', v_expected, v_actual;
  END IF;
