  INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref, created_at)
  VALUES (157, 6, $p24_b_157$[{"id": "b1-1-4-6-b1", "t": "list", "imp": "important", "title": "", "ordered": false, "items": ["1、^^远程医疗^^：", "（1）^^远程医疗以现代通信、计算机传感、遥测与遥控技术为依托，充分发挥大型综合医院或专科医疗中心的优质医疗技术与专家资源优势，对医疗条件相对薄弱的边远地区、海岛、基层医疗点或舰船上的伤病员开展远距离诊断、治疗、监护与医学咨询。^^", "（2）^^核心技术目标：打破优质医疗资源地理空间限制，提升急危重症救治率与基层诊疗规范化水平。^^", "（3）^^常见远程医疗系统组成与应用：①、以临床诊断治疗与双向转诊为目的的远程医疗诊断系统；②、以疑难杂症跨院多学科讨论为目的的远程医疗会诊系统；③、远程医学影像（PACS）阅片、心电监护与远程外科手术指导系统。^^"]}, {"t": "callout", "id": "b1-1-4-6-b2", "imp": "core", "kind": "tip", "text": "医院数字化核心系统：==HIS（医院信息系统，覆盖挂号、门诊收费、药品库存与住院病历等管理流）==与 ==CIS（临床信息系统，覆盖电子病历 EMR、实验室检验 LIS、手术麻醉与重症监护）==；远程医疗支持远程病理会诊、远程手术示教与远程监护。", "title": "考向复习提示：智慧医疗与医院两大核心信息系统"}, {"t": "callout", "id": "b1-1-4-6-b3", "imp": "core", "kind": "trap", "text": "专转本真题常考医疗信息化缩写：\n• ==PACS（医学影像存档与通信系统）==负责 CT、核磁共振 MRI、X 光片的数字化存储与网络调阅；\n• ==医学数字成像与通信必须严格遵循国际统一的“DICOM 标准”==；如果题目考查医学影像统一文件格式与通信规范，正确答案必然是 DICOM！", "title": "高频易错陷阱：PACS 系统与医疗影像 DICOM 国际标准"}]$p24_b_157$::jsonb, '', $p24_s_157$1、远程医疗：
（1）远程医疗以现代通信、计算机传感、遥测与遥控技术为依托，充分发挥大型综合医院或专科医疗中心的优质医疗技术与专家资源优势，对医疗条件相对薄弱的边远地区、海岛、基层医疗点或舰船上的伤病员开展远距离诊断、治疗、监护与医学咨询。
（2）核心技术目标：打破优质医疗资源地理空间限制，提升急危重症救治率与基层诊疗规范化水平。
（3）常见远程医疗系统组成与应用：①、以临床诊断治疗与双向转诊为目的的远程医疗诊断系统；②、以疑难杂症跨院多学科讨论为目的的远程医疗会诊系统；③、远程医学影像（PACS）阅片、心电监护与远程外科手术指导系统。
考向复习提示：智慧医疗与医院两大核心信息系统
医院数字化核心系统：HIS（医院信息系统，覆盖挂号、门诊收费、药品库存与住院病历等管理流）与 CIS（临床信息系统，覆盖电子病历 EMR、实验室检验 LIS、手术麻醉与重症监护）；远程医疗支持远程病理会诊、远程手术示教与远程监护。
高频易错陷阱：PACS 系统与医疗影像 DICOM 国际标准
专转本真题常考医疗信息化缩写：
• PACS（医学影像存档与通信系统）负责 CT、核磁共振 MRI、X 光片的数字化存储与网络调阅；
• 医学数字成像与通信必须严格遵循国际统一的“DICOM 标准”；如果题目考查医学影像统一文件格式与通信规范，正确答案必然是 DICOM！$p24_s_157$, $p24_r_157${"pdf": "理论复习.pdf", "extra": ["考纲三级节点: B1-1.4.6 远程医疗。", "p1_refine_20261114", "r1_cleanup_20261114", "24pdf_refine_20261114"], "pages": [96], "spans": 10}$p24_r_157$::jsonb, NOW());
  UPDATE kb_entry SET published_rev = 6, updated_at = NOW() WHERE node_id = 157;
END $$;

