END $$;

-- Node 240 (S1-1.2) rev 4 -> 5
DO $$
DECLARE
  v_actual INT;
  v_expected INT := 4;
BEGIN
  SELECT published_rev INTO v_actual FROM kb_entry WHERE node_id = 240 FOR UPDATE;
  IF v_actual IS DISTINCT FROM v_expected THEN
    RAISE EXCEPTION 'Optimistic lock mismatch for node 240: expected %, got %', v_expected, v_actual;
  END IF;
