  v_expected INT := 5;
BEGIN
  SELECT published_rev INTO v_actual FROM kb_entry WHERE node_id = 332 FOR UPDATE;
  IF v_actual IS DISTINCT FROM v_expected THEN
    RAISE EXCEPTION 'Optimistic lock mismatch for node 332: expected %, got %', v_expected, v_actual;
  END IF;
