-- Step 3: 提交前数据库级全量完整性断言
DO $$
DECLARE
  v_cnt INT;
  v_rev_sum BIGINT;
  v_cr_cnt INT;
  v_asset_cnt INT;
  v_new_asset INT;
  v_new_ref INT;
  v_tag_cnt INT;
BEGIN
  SELECT count(*), coalesce(sum(published_rev), 0) INTO v_cnt, v_rev_sum
    FROM kb_entry WHERE status = 'published';
  IF v_cnt <> 232 THEN
    RAISE EXCEPTION 'Expected 232 published entries, got %', v_cnt;
  END IF;
  IF v_rev_sum <> 1458 THEN
    RAISE EXCEPTION 'Expected published_rev sum 1458, got %', v_rev_sum;
  END IF;

  SELECT count(*) INTO v_cr_cnt
    FROM kb_entry e JOIN kb_revision r ON r.node_id = e.node_id AND r.rev_no = e.published_rev
   WHERE e.status = 'published' AND r.search_text LIKE '%' || E'\r' || '%';
  IF v_cr_cnt > 0 THEN
    RAISE EXCEPTION 'Found % published nodes with CR in search_text', v_cr_cnt;
  END IF;

  SELECT count(*) INTO v_tag_cnt
    FROM kb_entry e JOIN kb_revision r ON r.node_id = e.node_id AND r.rev_no = e.published_rev
   WHERE e.status = 'published' AND r.source_ref::text LIKE '%24pdf_refine_20261114%';
  IF v_tag_cnt <> 232 THEN
    RAISE EXCEPTION 'Expected 232 nodes tagged with 24pdf_refine_20261114, got %', v_tag_cnt;
  END IF;

  SELECT count(*) INTO v_asset_cnt FROM kb_asset;
  IF v_asset_cnt <> 455 THEN
    RAISE EXCEPTION 'Expected 455 total kb_asset rows, got %', v_asset_cnt;
  END IF;

  SELECT count(*) INTO v_new_asset FROM kb_asset WHERE path IN ('/kb-assets/pdf24/a1-mem-center.png', '/kb-assets/pdf24/a1-cu-workflow.png', '/kb-assets/pdf24/a2-sys-layers.png', '/kb-assets/pdf24/a2-tree-seq-array.png', '/kb-assets/pdf24/a3-mac-ip-encap.png', '/kb-assets/pdf24/a3-wan-comm-modes.png', '/kb-assets/pdf24/a3-packet-switch-vc.png', '/kb-assets/pdf24/a3-router-switch-mac.png', '/kb-assets/pdf24/a3-digital-sign-crypt.png', '/kb-assets/pdf24/b2-iot-three-layers.png', '/kb-assets/pdf24/b2-sensor-structure.png', '/kb-assets/pdf24/b3-android-arch.png', '/kb-assets/pdf24/b3-ios-harmony-arch.png', '/kb-assets/pdf24/b4-distributed-computing.png', '/kb-assets/pdf24/b4-virtualization-arch.png', '/kb-assets/pdf24/b5-mapreduce-flow.png', '/kb-assets/pdf24/b6-ml-rl-loop.png', '/kb-assets/pdf24/b6-neuron-mlp.png', '/kb-assets/pdf24/b7-blockchain-merkle.png');
  IF v_new_asset <> 19 THEN
    RAISE EXCEPTION 'Expected 19 new pdf24 assets in kb_asset, got %', v_new_asset;
  END IF;

  SELECT count(*) INTO v_new_ref
    FROM kb_asset a
   WHERE a.path IN ('/kb-assets/pdf24/a1-mem-center.png', '/kb-assets/pdf24/a1-cu-workflow.png', '/kb-assets/pdf24/a2-sys-layers.png', '/kb-assets/pdf24/a2-tree-seq-array.png', '/kb-assets/pdf24/a3-mac-ip-encap.png', '/kb-assets/pdf24/a3-wan-comm-modes.png', '/kb-assets/pdf24/a3-packet-switch-vc.png', '/kb-assets/pdf24/a3-router-switch-mac.png', '/kb-assets/pdf24/a3-digital-sign-crypt.png', '/kb-assets/pdf24/b2-iot-three-layers.png', '/kb-assets/pdf24/b2-sensor-structure.png', '/kb-assets/pdf24/b3-android-arch.png', '/kb-assets/pdf24/b3-ios-harmony-arch.png', '/kb-assets/pdf24/b4-distributed-computing.png', '/kb-assets/pdf24/b4-virtualization-arch.png', '/kb-assets/pdf24/b5-mapreduce-flow.png', '/kb-assets/pdf24/b6-ml-rl-loop.png', '/kb-assets/pdf24/b6-neuron-mlp.png', '/kb-assets/pdf24/b7-blockchain-merkle.png')
     AND EXISTS (
       SELECT 1 FROM kb_entry e JOIN kb_revision r ON r.node_id = e.node_id AND r.rev_no = e.published_rev
        WHERE e.status = 'published' AND r.blocks::text LIKE '%' || a.path || '%'
     );
  IF v_new_ref <> 19 THEN
    RAISE EXCEPTION 'Expected all 19 new pdf24 assets referenced in published revisions, got %', v_new_ref;
  END IF;
END $$;

COMMIT;
